    for(String key:Arrays.asList("topLevelDocument","dedicatedWorker","boundedWorkerReply","crossOriginFrame")){JSONObject changed=copy(v);changed.getJSONObject("service").getJSONObject("capabilities").put(key,"true");errorControl("invalid typed capability "+key,changed,"capabilities-incomplete");}
    JSONObject limited=copy(v);limited.getJSONObject("service").getJSONObject("capabilities").put("dedicatedWorker",false);JSONObject absent=RequestIdentityServiceProbe.evaluate(limited,n,BASE);check("typed missing worker support is unavailable","unavailable".equals(absent.optString("status"))&&"required-capability-unavailable".equals(absent.optString("reason")));
    for(String key:Arrays.asList("checkTtlMs","maxConcurrentChecks","maxCheckEvents","workerResponseBytes")){JSONObject changed=copy(v);changed.getJSONObject("service").getJSONObject("limits").put(key,-1);errorControl("negative limit rejected "+key,changed,"capabilities-incomplete");}
    for(Object count:new Object[]{0,16385,"1000",Double.NaN}){JSONObject changed=copy(v);if(count instanceof Double&&Double.isNaN((Double)count))changed.remove("responseBytes");else changed.put("responseBytes",count);errorControl("actual bounded byte count required "+count,changed,"response-size-unconfirmed");}
