final class FakeHandler {static final class Task{long at;Runnable run;Task(long a,Runnable r){at=a;run=r;}}final List<Task> queue=new ArrayList<>();void postDelayed(Runnable r,long delay){queue.add(new Task(android.os.SystemClock.now+delay,r));}void removeCallbacks(Runnable r){queue.removeIf(t->t.run==r);}void advance(long ms){long until=android.os.SystemClock.now+ms;for(;;){Task next=queue.stream().filter(t->t.at<=until).min(Comparator.comparingLong(t->t.at)).orElse(null);if(next==null)break;queue.remove(next);android.os.SystemClock.now=next.at;next.run.run();}android.os.SystemClock.now=until;}}
