final class GeckoWebView {EnvironmentAudit owner;boolean visible=true,protectedRoute=true,automatic,automaticRegistration,frame;String url="https://chatgpt.com/c/fixture",ackPurpose="capabilities";int admissions;Consumer<String> registerReply,capabilityReply;final List<JSONObject> calls=new ArrayList<>();static boolean active(GeckoWebView v){return v!=null;}boolean hasVisibleDocument(){return visible;}boolean protectionAllowsNetwork(){return protectedRoute;}String getUrl(){return url;}void requestIdentityScope(JSONObject value,Consumer<String> callback){JSONObject request=J.parse(value.toString());calls.add(request);String kind=request.optString("action"),n=request.optString("nonce");if(kind.equals("register")){registerReply=callback;if(automatic||automaticRegistration)callback.accept(J.obj("ok",true,"nonce",n,"purpose",ackPurpose,"credentialFilter",true,"redirectsBlocked",true).toString());}else if(kind.equals("capabilities")){if(owner.serviceProbe.allowsRequest(RequestIdentityServiceProbeHost.BASE+"capabilities?nonce="+n))admissions++;else throw new AssertionError("Native service request admission denied");capabilityReply=callback;if(automatic)callback.accept(RequestIdentityServiceProbeHost.control(n,frame).toString());}else callback.accept(J.obj("ok",true,"nonce",n).toString());}}
